// The plan is a DAG of TAGS. This node walks it, groups independent nodes for parallel
// execution, and emits one dispatch item per production subsystem. It never names a
// provider, a platform or a vertical — that is the router's job, one layer down.
const plan = $('Compose Plan').first().json;
const brief = $('Intake & Understand').first().json;

const SUBSYSTEM = {
  'produce.copy.longform': 'sub.content', 'produce.copy.short': 'sub.content', 'produce.script': 'sub.content', 'produce.localize': 'sub.content', 'research.market': 'sub.content', 'research.product': 'sub.content',
  'produce.image.prompt': 'sub.visual', 'produce.image': 'sub.visual', 'produce.image.edit': 'sub.visual', 'asset.search': 'sub.visual',
  'produce.video.clip': 'sub.motion', 'produce.audio.vo': 'sub.motion', 'produce.captions': 'sub.motion', 'assemble.video': 'sub.motion',
  'verify.brand': 'sub.governance', 'verify.compliance': 'sub.governance', 'verify.rights': 'sub.governance', 'approve.human': 'sub.governance',
  'distribute.publish': 'sub.distribution', 'distribute.schedule': 'sub.distribution',
  'measure.collect': 'sub.measurement', 'measure.score': 'sub.measurement', 'learn.update': 'sub.measurement'
};

const needed = new Set((plan.nodes || []).map(n => SUBSYSTEM[n.tag]).filter(Boolean));
const production = ['sub.content', 'sub.visual', 'sub.motion'].filter(s => needed.has(s));

return production.map(subsystem => ({ json: {
  subsystem,
  brief,
  plan,
  channel_allocation: plan.channel_allocation,
  params: Object.fromEntries((plan.nodes || []).filter(n => SUBSYSTEM[n.tag] === subsystem).map(n => [n.tag, n.params]))
} }));

// Saga rollback. Walk provenance BACKWARDS and invoke each entry's declared compensation.
// Entries with no compensation (a delivered Telegram message, a sent email) are reported as
// irreversible rather than silently skipped — an operator needs to know what is still out there.
const env = $('Envelope In').first().json;
const REGISTRY = JSON.parse($env.MOS_CAPABILITY_REGISTRY || '{}');
const steps = [...(env.provenance || [])].reverse();
const toCompensate = [], irreversible = [];
for (const s of steps) {
  const cap = REGISTRY[s.capability];
  if (!cap) continue;
  if (['external_write', 'publish', 'spend'].includes(cap.side_effects)) {
    if (cap.compensation) toCompensate.push({ capability: cap.compensation, for: s.capability, span: s.at });
    else irreversible.push(s.capability);
  }
}
return [{ json: { compensations: toCompensate, irreversible, requires_operator_notice: irreversible.length > 0 } }];

