// Not every run should produce content. A thin brief, no matching play, or an unaffordable
// plan all end here — visibly, with a reason, rather than by producing something nobody wanted.
const reasons = {
  low_confidence: 'The request was too ambiguous to act on; a clarifying question was sent instead.',
  no_fit: 'No declared play fits this request. A human needs to either widen the brief or add a play.',
  budget: 'The plan costs more than this run is allowed to spend.'
};
const r = $json.no_fit ? 'no_fit' : ($json.decision === 'deny' ? 'budget' : 'low_confidence');
return [{ json: { terminal_state: 'declined', reason: r, human_summary: reasons[r], needs_attention: r !== 'low_confidence' } }];
